"""Certified exact computation of the multiplicity N(t) of t in Pascal's triangle.

N(t) = #{(n,k) : k <= n, C(n,k) = t}.  For t >= 3 the two boundary occurrences
(t,1) and (t,t-1) are always present; every other occurrence is interior, i.e.
2 <= k <= n-2, and then C(n,2) <= C(n,k) = t, which caps the row index n by the
least N with t < C(N,2), i.e. n = O(sqrt(t)).  Inside that box the test
C(n,k) = t is performed through descending factorials, costing k multiplications
instead of Theta(n k) additions.
"""

from __future__ import annotations

from math import comb, factorial
from typing import List, Tuple

Position = Tuple[int, int]


def descending_factorial(n: int, k: int) -> int:
    """n (n-1) ... (n-k+1) = k! * C(n,k).  Cost: k multiplications."""
    result = 1
    for i in range(k):
        result *= n - i
    return result


def choose_equals(n: int, k: int, t: int) -> bool:
    """Decide C(n,k) == t without ever forming C(n,k) by Pascal recursion."""
    if k > n:
        return t == 0
    return descending_factorial(n, k) == factorial(k) * t


def row_window(t: int) -> int:
    """Least N >= 2 with t < C(N,2); every interior occurrence has n < N."""
    n = 2
    while comb(n, 2) <= t:
        n += 1
    return n


def exact_occurrences(t: int) -> List[Position]:
    """All positions of t in Pascal's triangle, sorted.  Requires t >= 2."""
    if t < 2:
        raise ValueError("t must be at least 2")
    if t == 2:
        return [(2, 1)]
    positions: List[Position] = [(t, 1), (t, t - 1)]
    limit = row_window(t)
    for n in range(4, limit):
        for k in range(2, n // 2 + 1):
            if k <= n - 2 and choose_equals(n, k, t):
                positions.append((n, k))
                if k != n - k:
                    positions.append((n, n - k))
    return sorted(set(positions))


def multiplicity(t: int) -> int:
    """N(t)."""
    return len(exact_occurrences(t))


if __name__ == "__main__":
    for value in (2, 3, 6, 10, 120, 210, 1540, 3003, 7140, 11628, 24310):
        pos = exact_occurrences(value)
        print(f"N({value}) = {len(pos)}  at  " +
              ", ".join(f"C({n},{k})" for n, k in pos))
